-- AC 11's third arm needs a Schedule 11 DATA row on each happy-path mill, or "BASIC_SILVICULTURE_REPORT
-- unchanged" is asserted against nothing. Seeded AFTER the mills' status and category rows (category '11'
-- exists on both), with the catalogue row every other Schedule 11 fixture uses. UPDATE_USERID is left
-- NULL on purpose: the ITs assert the row reads 'Reversal Block 79x/-/r0' after the reversal, so a stray
-- stamp or revision bump on this table changes the string. Ids sit inside the claimed 1650-1699 band and
-- below ILCR_REPORT_COMMON_SEQ (9500), which Schedule 11's write path draws from.
INSERT INTO THE.BASIC_SILVICULTURE_REPORT (BASIC_SILVICULTURE_REPORT_ID, REPORT_YEAR, ILCR_MILL_ID, ILCR_CATEGORY_ID, LOCATION, BECBIOGEOCLIMATIC_CATALOGUE_ID, REFORESTED_NET_AREA, ENHANCED_IND, COMMENTS, REVISION_COUNT, ENTRY_USERID)
  SELECT 1690, 2021, 790, '11', 'Reversal Block 790', 8801, 40, 'N', NULL, 0, 'SEED' FROM DUAL
   WHERE NOT EXISTS (SELECT 1 FROM THE.BASIC_SILVICULTURE_REPORT WHERE BASIC_SILVICULTURE_REPORT_ID = 1690);
INSERT INTO THE.BASIC_SILVICULTURE_REPORT (BASIC_SILVICULTURE_REPORT_ID, REPORT_YEAR, ILCR_MILL_ID, ILCR_CATEGORY_ID, LOCATION, BECBIOGEOCLIMATIC_CATALOGUE_ID, REFORESTED_NET_AREA, ENHANCED_IND, COMMENTS, REVISION_COUNT, ENTRY_USERID)
  SELECT 1691, 2021, 791, '11', 'Reversal Block 791', 8801, 40, 'N', NULL, 0, 'SEED' FROM DUAL
   WHERE NOT EXISTS (SELECT 1 FROM THE.BASIC_SILVICULTURE_REPORT WHERE BASIC_SILVICULTURE_REPORT_ID = 1691);
